lib='''def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def components(grid, color=None):
    """All 4-connected same-color components (as cell lists), optionally restricted to one color."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    comps = []
    for i in range(h):
        for j in range(w):
            if seen[i][j] or (color is not None and grid[i][j] != color):
                continue
            if color is None and grid[i][j] is None:
                continue
            c = grid[i][j]
            if color is None and c == 0 and False:
                pass
            stack = [(i, j)]; seen[i][j] = True; comp = []
            while stack:
                y, x = stack.pop(); comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == c:
                        seen[ny][nx] = True; stack.append((ny, nx))
            comps.append(comp)
    return comps

def bbox(grid, cells, color):
    """Fill cells' bounding rectangle in a copy of grid with color (grid unchanged unless copy given)."""
    ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
    return min(ys), min(xs), max(ys), max(xs)

def fill_components(grid, min_size=3):
    """Each connected component of at least min_size cells becomes a solid rectangle of its color; all other cells become the background color."""
    h, w = len(grid), len(grid[0])
    bg = background(grid)
    res = [[bg]*w for _ in range(h)]
    for comp in components(grid):
        if len(comp) >= min_size:
            t, l, b, r = bbox(grid, comp, grid[comp[0][0]][comp[0][1]])
            col = grid[comp[0][0]][comp[0][1]]
            for y in range(t, b+1):
                for x in range(l, r+1):
                    res[y][x] = col
    return res
